export interface Profunctor2 {
    readonly dimap: (f: (s: any) => any, g: (b: any) => any, p: any) => any;
    readonly first?: (p: any) => any;
    readonly left?: (p: any) => any;
    readonly wander?: (traverse: any, p: any) => any;
