export type Optic<S, A> = (P: Profunctor2) => (pab: any) => (s: S) => any;

export type Lens<S, A> = Optic<S, A>;
export type Prism<S, A> = Optic<S, A>;
export type Traversal<S, A> = Optic<S, A>;''')
